# ---------------------------------------------------------------- схемы для коротких слайдов SONET/SDH
from _scoob import scp, chip, lbl, ln, env, flow, OUT, OR, CY  # noqa: E402

RING = "M300,40 C440,40 500,90 500,150 C500,210 440,260 300,260 C160,260 100,210 100,150 C100,90 160,40 300,40"


def _ring(t=""):
    g = ln(RING, CY, 7) + "".join(chip(x, y, "ADM", "#7fe3e0", 16) for x, y in ((300, 45), (500, 155), (300, 265), (100, 155)))
    g += "".join(chip(x, y, "R", "#d7f27a", 14) for x, y in ((440, 75), (450, 235), (160, 235), (160, 75)))
    g += env(RING, 0, 4.6, 5) + env(RING, 2.3, 4.6, 5) + lbl(300, 150, "Кольцо", 18) + lbl(300, 172, "SONET/SDH", 18)
    g += "".join(ln("M%d,%d h-%d" % (60, 140 + k * 10, 60), OR, 4) for k in range(3)) + lbl(30, 120, "E1", 15)
    g += "".join(ln("M%d,%d h60" % (540, 140 + k * 10), CY, 4) for k in range(3)) + lbl(580, 120, "STM-1", 15)
    return scp(g, t, 640, 300)


def _levels():
    xs = [70, 230, 420, 610, 770]
    g = ln("M70,40 L770,40", OUT, 3) + "".join(chip(x, 40, t, f, 15) for x, t, f in zip(xs, ("Терминал", "R", "ADM", "R", "Терминал"),
                                                                                    ("#ffd27a", "#d7f27a", "#7fe3e0", "#d7f27a", "#ffd27a")))
    g += env("M70,40 L770,40", 0, 3.5, 4)
    for y, t, segs, c in ((100, "Section", [(70, 230), (230, 420), (420, 610), (610, 770)], OR), (150, "Line", [(70, 420), (420, 770)], CY), (200, "Path", [(70, 770)], "#ff5ca8")):
        g += lbl(10, y + 5, t, 15, anchor="start") + "".join(ln("M%d,%d L%d,%d" % (a + 6, y, b - 6, y), c, 6) for a, b in segs)
    return scp(g, "", 820, 230)


for _k, _sc in (("Кольцо SONET/SDH", _ring), ("Кольцо SONET/SDH: принцип работы", _ring), ("Уровни передачи SONET/SDH", _levels), ("Как взаимодействуют уровни", _levels)):
    _s, _h = TX[_k]
    TX[_k] = (_s, stack(_h, _sc()))
